function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 characters.';
  if (!/^[abc]+$/.test(s)) return "s may contain only 'a', 'b' and 'c'.";
  if (!Number.isInteger(k) || k < 0 || k > s.length) return 'k is an integer from 0 to s.length.';
  return null;
}

