function takeCharacters(s, k) {
  const total = [0, 0, 0];
  for (let i = 0; i < s.length; i++) {
    total[s.charCodeAt(i) - 97]++;
  }
  if (total.some(count => count < k)) return -1;

  const kept = [0, 0, 0];
  let left = 0;
  let longest = 0;
  for (let right = 0; right < s.length; right++) {
    const added = s.charCodeAt(right) - 97;
    kept[added]++;
    while (kept[added] > total[added] - k) {
      kept[s.charCodeAt(left) - 97]--;
      left++;
    }
    longest = Math.max(longest, right - left + 1);
  }
  return s.length - longest;
}

