function takeCharacters(s, k) {
  const n = s.length;
  let best = -1;
  for (let fromLeft = 0; fromLeft <= n; fromLeft++) {
    for (let fromRight = 0; fromLeft + fromRight <= n; fromRight++) {
      const taken = s.slice(0, fromLeft) + s.slice(n - fromRight);
      const count = ch => taken.split('').filter(x => x === ch).length;
      if (count('a') >= k && count('b') >= k && count('c') >= k) {
        if (best === -1 || fromLeft + fromRight < best) best = fromLeft + fromRight;
      }
    }
  }
  return best;
}

