function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(8000, 10000) : int(1, 12);
  // Uneven letter weights give long runs of one letter and scarce letters.
  const weights = [rand() + 0.05, rand() + 0.05, rand() + 0.05];
  const sum = weights[0] + weights[1] + weights[2];
  let s = '';
  for (let i = 0; i < n; i++) {
    const pick = rand() * sum;
    s += pick < weights[0] ? 'a' : pick < weights[0] + weights[1] ? 'b' : 'c';
  }
  const fewest = Math.min(...['a', 'b', 'c'].map(ch => s.split(ch).length - 1));
  const k = rand() < 0.15 ? Math.min(n, fewest + int(1, 3)) : int(0, fewest);
  return [s, k];
}
